<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; class StudentController extends Controller { public function index(Request $request) { $students = User::where("role","student")->withCount("bookings")->when($request->filled("search"),function($q) use ($request) { $s = $request->input("search"); $q->where(function($x) use ($s) { $x->where("name","like","%".$s."%")->orWhere("nim","like","%".$s."%")->orWhere("email","like","%".$s."%")->orWhere("study_program","like","%".$s."%"); }); })->orderBy("name")->paginate(10)->withQueryString(); return view("admin.students.index",compact("students")); } public function show(User $student) { abort_unless($student->role === "student",404); $bookings = $student->bookings()->with("room")->latest("id")->paginate(10); return view("admin.students.show",compact("student","bookings")); } }
